/**
 * @brief Classifier model read: header, CTRL/STATUS from MODE, other words as
 *        written (counters and policer statistics are set by the harness).
 * @param off Offset in the 4 KiB window.
 * @return Register value.
 */
static uint32_t host_cls_read(uint32_t off)
{
    switch (off) {
    case RTLNET_CLS_REG_ID:      return RTLNET_CLS_ID_VALUE;
    case RTLNET_CLS_REG_VERSION: return RTLNET_CLS_VERSION_VALUE;
    case RTLNET_CLS_REG_CAPS:    return HOST_CLS_CAPS;
    case RTLNET_CLS_REG_CTRL:    return g_cls_mode;
    case RTLNET_CLS_REG_STATUS:  return g_cls_mode << RTLNET_CLS_STATUS_MODE_SHIFT;
    case RTLNET_CLS_REG_LATENCY: return HOST_CLS_LATENCY;
    default:                     return g_cls_mem[(off / 4u) % HOST_CLS_WORDS];
    }
}

/**
 * @brief Classifier model write: MODE, CLEAR_TABLES (everything back to the
 *        power-up state) and plain storage for the other words.
 * @param off   Offset in the 4 KiB window.
 * @param value Value.
 * @return None.
 */
static void host_cls_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_CLS_REG_CTRL) {
        if ((value & RTLNET_CLS_CTRL_CLEAR_TABLES) != 0u) {
            memset(g_cls_mem, 0, sizeof(g_cls_mem));
            g_cls_mode = 0u;
        } else {
            g_cls_mode = value & RTLNET_CLS_CTRL_MODE_MASK;
        }
    } else if (off >= RTLNET_CLS_REG_TABLE_MODE(0u)) {
        g_cls_mem[(off / 4u) % HOST_CLS_WORDS] = value;
    }
}

/**
 * @brief Classifier model word as the harness sees it (also CTRL and STATUS).
 * @param offset Offset in the 4 KiB window.
 * @return Register value.
 */
uint32_t host_model_cls_peek(uint32_t offset)
{
    return host_cls_read(offset);
}

/**
 * @brief Set a classifier model word directly (counters, policer statistics).
 * @param offset Offset in the 4 KiB window.
 * @param value  Value.
 * @return None.
 */
void host_model_cls_poke(uint32_t offset, uint32_t value)
{
    g_cls_mem[(offset / 4u) % HOST_CLS_WORDS] = value;
}

/**
 * @brief DDR3 path model: the arbiter window present, the calibration bit.
 * @param arbiter_present 1 when the arbiter window answers.
 * @param calibrated      1 when CLK_STATUS shows init_calib_complete.
 * @return None.
 */
void host_model_ddr_set(int arbiter_present, int calibrated)
{
    g_ddr_arb_on = arbiter_present;
    g_ddr_cal    = calibrated;
}

/**
 * @brief Fault injection: address bit stuck low in the memory window.
 * @param bit Bit number (2..28); 0 removes the fault.
 * @return None.
 */
void host_model_ddr_alias_bit(unsigned bit)
{
    g_ddr_alias = bit;
}

/**
 * @brief Fault injection: AND mask applied to every word read from the window.
 * @param mask Mask (0xFFFFFFFF = no fault).
 * @return None.
 */
void host_model_ddr_data_and(uint32_t mask)
{
    g_ddr_and = mask;
}

/**
 * @brief Set the arbiter's sticky illegal-burst flag and count one error.
 * @return None.
 */
void host_model_ddr_error(void)
{
    g_arb_err = 1;
    g_arb_cnt[0][4]++;
}

/**
 * @brief Empty the memory window, clear the counters, the error flag and the injected faults.
 * @return None.
 */
void host_model_ddr_clear(void)
{
    for (size_t i = 0; i < HOST_DDR_PAGES; i++) {
        free(g_ddr_page[i]);
        g_ddr_page[i] = NULL;
    }
    memset(g_arb_cnt, 0, sizeof(g_arb_cnt));
    g_arb_err   = 0;
    g_ddr_alias = 0u;
    g_ddr_and   = 0xFFFFFFFFu;
}

/**
 * @brief Page of the memory window holding an address.
 * @param addr   Byte address inside the window.
 * @param create 1 allocates a missing page.
 * @return Page (HOST_DDR_PAGE_BYTES / 4 words) or NULL (absent, or outside the window).
 */
static uint32_t *host_ddr_page(uintptr_t addr, int create)
{
    uint32_t off;
    uint32_t idx;
    if (addr < RTLNET_PLAT_DDR_BASE || addr - RTLNET_PLAT_DDR_BASE >= RTLNET_PLAT_DDR_SIZE) {
        return NULL;
    }
    off = (uint32_t)(addr - RTLNET_PLAT_DDR_BASE);
    if (g_ddr_alias != 0u) {
        off &= ~(1u << g_ddr_alias);
    }
    idx = off / HOST_DDR_PAGE_BYTES;
    if (g_ddr_page[idx] == NULL && create) {
        g_ddr_page[idx] = (uint32_t *)calloc(HOST_DDR_PAGE_BYTES / 4u, sizeof(uint32_t));
    }
    return g_ddr_page[idx];
}

/**
 * @brief Memory window word index of an address (aliasing applied).
 * @param addr Byte address inside the window.
 * @return Word index inside its page.
 */
static uint32_t host_ddr_word(uintptr_t addr)
{
    uint32_t off = (uint32_t)(addr - RTLNET_PLAT_DDR_BASE);
    if (g_ddr_alias != 0u) {
        off &= ~(1u << g_ddr_alias);
    }
    return (off % HOST_DDR_PAGE_BYTES) / 4u;
}

/**
 * @brief ddrtest host hook: word read from the DDR3 window model.
 * @param addr Byte address.
 * @return Stored word (0 for a never-written word), the injected data mask applied.
 */
uint32_t rtlnet_host_mem_read32(uintptr_t addr)
{
    uint32_t *pg = host_ddr_page(addr, 0);
    g_arb_cnt[0][1]++;
    g_arb_cnt[0][3]++;
    return ((pg != NULL) ? pg[host_ddr_word(addr)] : 0u) & g_ddr_and;
}

/**
 * @brief ddrtest host hook: word write into the DDR3 window model.
 * @param addr  Byte address.
 * @param value Word.
 * @return None.
 */
void rtlnet_host_mem_write32(uintptr_t addr, uint32_t value)
{
    uint32_t *pg = host_ddr_page(addr, 1);
    g_arb_cnt[0][0]++;
    g_arb_cnt[0][2]++;
    if (pg != NULL) {
        pg[host_ddr_word(addr)] = value;
    }
}

/**
 * @brief Model of the arbiter register read mux.
 * @param off Register offset.
 * @return Register value.
 */
static uint32_t host_arb_read(uint32_t off)
{
    switch (off) {
    case RTLNET_REG_ID:           return RTLNET_ARB_ID_VALUE;
    case RTLNET_REG_VERSION:      return RTLNET_ARB_VERSION_VALUE;
    case RTLNET_REG_CAPS:         return HOST_ARB_CAPS;
    case RTLNET_ARB_REG_STATUS:   return g_arb_err ? RTLNET_ARB_STATUS_ERR : 0u;
    case RTLNET_ARB_REG_NARROW:   return 0x01u;      /* master 0 (CPU caches) */
    case RTLNET_ARB_REG_WRAP:     return 0x01u;
    default:
        if (off >= RTLNET_ARB_MASTER_BASE && off < RTLNET_ARB_MASTER_BASE + 2u * RTLNET_ARB_MASTER_STRIDE && (off & 3u) == 0u &&
            ((off - RTLNET_ARB_MASTER_BASE) % RTLNET_ARB_MASTER_STRIDE) / 4u < 6u) {
            return g_arb_cnt[(off - RTLNET_ARB_MASTER_BASE) / RTLNET_ARB_MASTER_STRIDE]
                            [((off - RTLNET_ARB_MASTER_BASE) % RTLNET_ARB_MASTER_STRIDE) / 4u];
        }
        return 0u;
    }
}

/**
 * @brief Model of the arbiter register writes: CTRL.CNT_CLEAR and STATUS.ERR write-1-to-clear.
 * @param off   Register offset.
 * @param value Value.
 * @return None.
 */
static void host_arb_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_ARB_REG_CTRL && (value & RTLNET_ARB_CTRL_CNT_CLEAR) != 0u) {
        memset(g_arb_cnt, 0, sizeof(g_arb_cnt));
    } else if (off == RTLNET_ARB_REG_STATUS && (value & RTLNET_ARB_STATUS_ERR) != 0u) {
        g_arb_err = 0;
    }
}

/* ---------------------------------------------------------------------------
 * Video cores model (Phase 1): the register windows of rtlnet_csi2_rx, rtlnet_vdma_s2mm and rtlnet_framebuf, with
 * bar frames written into the memory window when the firmware takes a slot. The frame count is set by the harness
 * (host_model_video_frames); the model publishes frame k into slot (k - 1) % 3.
 * ------------------------------------------------------------------------- */
#define HOST_VID_VERSION     0x11092026u
#define HOST_VID_FB_OFFSET   0x10000000u   /* DDR3 offset of slot 0 */
#define HOST_VID_SLOTS       3u
#define HOST_VID_SLOT_LOG2   22u
#define HOST_VID_SLOT_BYTES  (1u << HOST_VID_SLOT_LOG2)
#define HOST_VID_PERIOD_RST  3000000u
#define HOST_VID_BARS        8u
#define HOST_VID_ERR_FB      (1u << 3)     /* FBUF STATUS.FW_ERR */

static int       g_vid_on;
static uint32_t  g_vid_frames;             /* frames the model has sent */
static uint32_t  g_vid_base;               /* frame count at the last CNT_CLEAR */
static uint32_t  g_csi_mode;
static uint32_t  g_csi_src;
static uint32_t  g_csi_period = HOST_VID_PERIOD_RST;
static uint32_t  g_csi_timeout = RTLNET_CSI2_CAM_TIMEOUT_RESET;
static uint32_t  g_csi_err;                /* STATUS bits [6:2] */
static uint32_t  g_csi_pattern = 4u << RTLNET_CSI2_PATTERN_SPEED_SHIFT;   /* PATTERN reset: static bars, speed 4 */
static uint32_t  g_dma_ctrl = RTLNET_S2MM_CTRL_ENABLE;
static uint32_t  g_dma_stride;
static int       g_fb_holds;
static uint32_t  g_fb_fw_slot;
static uint32_t  g_fb_fw_frame;
static uint32_t  g_fb_fw_mode;
static uint32_t  g_fb_err;
static uint32_t  g_fb_takes;

/* Bar colors: Y, Cb, Cr of white, yellow, cyan, green, magenta, red, blue, black. */
static const uint8_t g_vid_bar[HOST_VID_BARS][3] = {
    { 180u, 128u, 128u }, { 168u, 44u, 136u }, { 145u, 147u, 44u }, { 133u, 63u, 52u },
    { 63u, 193u, 204u }, { 51u, 109u, 212u }, { 28u, 212u, 120u }, { 16u, 128u, 128u }
};

/**
 * @brief Present or remove the video cores (the three windows answer 0 when absent).
 * @param present 1 when the windows answer.
 * @return None.
 */
void host_model_video_set(int present)
{
    g_vid_on      = present;
    g_vid_frames  = 0u;
    g_vid_base    = 0u;
    g_csi_mode    = RTLNET_CSI2_MODE_720P30;
    g_csi_src     = RTLNET_CSI2_SRC_AUTO;
    g_csi_period  = HOST_VID_PERIOD_RST;
    g_csi_timeout = RTLNET_CSI2_CAM_TIMEOUT_RESET;
    g_csi_err     = 0u;
    g_csi_pattern = 4u << RTLNET_CSI2_PATTERN_SPEED_SHIFT;
    g_dma_ctrl    = RTLNET_S2MM_CTRL_ENABLE;
    g_dma_stride  = 0u;
    g_fb_holds    = 0;
    g_fb_err      = 0u;
    g_fb_takes    = 0u;
}

/**
 * @brief Set the number of frames the model has sent and published.
 * @param frames Frame count.
 * @return None.
 */
void host_model_video_frames(uint32_t frames)
{
    g_vid_frames = frames;
}

/**
 * @brief Slot a frame was published into.
 * @param frame Frame number (1-based).
 * @return Slot index.
 */
static uint32_t host_vid_slot(uint32_t frame)
{
    return (frame == 0u) ? 0u : ((frame - 1u) % HOST_VID_SLOTS);
}

/**
 * @brief Minimum FRAME_PERIOD of a mode.
 * @param mode VIDEO_MODE value.
 * @return ui_clk cycles.
 */
static uint32_t host_vid_min_period(uint32_t mode)
{
    return (mode == RTLNET_CSI2_MODE_1080P30) ? RTLNET_CSI2_PERIOD_MIN_1080P30 : RTLNET_CSI2_PERIOD_MIN_720P30;
}

/**
 * @brief Write the bar frame of a mode into a slot of the memory window, lines at the STRIDE (0 = packed).
 * @param slot Slot index.
 * @param mode VIDEO_MODE value.
 * @return None.
 */
static void host_vid_fill(uint32_t slot, uint32_t mode)
{
    uint32_t w = rtlnet_csi2_rx_mode_width(mode);
    uint32_t h = rtlnet_csi2_rx_mode_height(mode);
    uint32_t stride = (g_dma_stride != 0u) ? g_dma_stride : (w * RTLNET_CSI2_BYTES_PER_PIXEL);
    uintptr_t base = RTLNET_PLAT_DDR_BASE + HOST_VID_FB_OFFSET + ((uintptr_t)slot * HOST_VID_SLOT_BYTES);

    for (uint32_t y = 0u; y < h; y++) {
        for (uint32_t x = 0u; x < w / 2u; x++) {
            uint32_t bar = (x * 2u) / (w / HOST_VID_BARS);
            uint32_t yy = g_vid_bar[bar][0];
            uint32_t word = yy | ((uint32_t)g_vid_bar[bar][1] << 8) | (yy << 16) | ((uint32_t)g_vid_bar[bar][2] << 24);
            uintptr_t a = base + ((uintptr_t)y * stride) + ((uintptr_t)x * 4u);
            uint32_t *pg = host_ddr_page(a, 1);
            if (pg != NULL) {
                pg[host_ddr_word(a)] = word;
            }
        }
    }
}

/**
 * @brief Model of the rtlnet_csi2_rx register read mux.
 * @param off Register offset.
 * @return Register value.
 */
static uint32_t host_csi2_read(uint32_t off)
{
    switch (off) {
    case RTLNET_REG_ID:                  return RTLNET_CSI2_ID_VALUE;
    case RTLNET_REG_VERSION:             return RTLNET_CSI2_VERSION_VALUE;
    case RTLNET_REG_CAPS:                return RTLNET_CSI2_MODE_COUNT | RTLNET_CSI2_CAPS_PATTERN | RTLNET_CSI2_CAPS_MOVING;
    case RTLNET_CSI2_REG_VIDEO_MODE:     return g_csi_mode;
    case RTLNET_CSI2_REG_SOURCE:         return g_csi_src;
    case RTLNET_CSI2_REG_FRAME_PERIOD:   return g_csi_period;
    case RTLNET_CSI2_REG_CAM_TIMEOUT:    return g_csi_timeout;
    case RTLNET_CSI2_REG_STATUS:         return ((g_csi_src != RTLNET_CSI2_SRC_CAMERA) ? RTLNET_CSI2_STATUS_PATTERN : 0u) | g_csi_err;
    case RTLNET_CSI2_REG_FRAME_COUNT:    return g_vid_frames;
    case RTLNET_CSI2_REG_ACTIVE:         return g_csi_mode;
    case RTLNET_CSI2_REG_PATTERN:        return g_csi_pattern;
    case RTLNET_CSI2_REG_PATTERN_FRAME:  return 0u;
    default:                             return 0u;
    }
}

/**
 * @brief Model of the rtlnet_csi2_rx register writes: rejections set the sticky flags, STATUS is write-1-to-clear.
 * @param off   Register offset.
 * @param value Value.
 * @return None.
 */
static void host_csi2_write(uint32_t off, uint32_t value)
{
    switch (off) {
    case RTLNET_CSI2_REG_VIDEO_MODE:
        if (value >= RTLNET_CSI2_MODE_COUNT) {
            g_csi_err |= RTLNET_CSI2_STATUS_MODE_ERR;
        } else if (g_csi_period < host_vid_min_period(value)) {
            g_csi_err |= RTLNET_CSI2_STATUS_PERIOD_ERR;
        } else {
            g_csi_mode = value;
        }
        break;
    case RTLNET_CSI2_REG_SOURCE:
        if (value > RTLNET_CSI2_SRC_PATTERN) {
            g_csi_err |= RTLNET_CSI2_STATUS_SOURCE_ERR;
        } else {
            g_csi_src = value;
        }
        break;
    case RTLNET_CSI2_REG_FRAME_PERIOD:
        if (value < host_vid_min_period(g_csi_mode)) {
            g_csi_err |= RTLNET_CSI2_STATUS_PERIOD_ERR;
        } else {
            g_csi_period = value;
        }
        break;
    case RTLNET_CSI2_REG_CAM_TIMEOUT:
        g_csi_timeout = value;
        break;
    case RTLNET_CSI2_REG_PATTERN: {
        int32_t speed = (int32_t)(int8_t)(uint8_t)(value >> RTLNET_CSI2_PATTERN_SPEED_SHIFT);
        if ((value & ~0x0000FF07u) != 0u || (value & 7u) >= RTLNET_CSI2_PATTERN_COUNT || speed < -32 || speed > 32) {
            g_csi_err |= RTLNET_CSI2_STATUS_PATTERN_ERR;
        } else {
            g_csi_pattern = value;
        }
        break;
    }
    case RTLNET_CSI2_REG_STATUS:
        g_csi_err &= ~(value & RTLNET_CSI2_STATUS_ERR_MASK);
        break;
    default:
        break;
    }
}

/**
 * @brief Model of the rtlnet_vdma_s2mm register read mux.
 * @param off Register offset.
 * @return Register value.
 */
static uint32_t host_s2mm_read(uint32_t off)
{
    uint32_t ok = g_vid_frames - g_vid_base;
    uint32_t beats = rtlnet_csi2_rx_mode_height(g_csi_mode) * ((rtlnet_csi2_rx_mode_width(g_csi_mode) * RTLNET_CSI2_BYTES_PER_PIXEL) /
                                                              RTLNET_S2MM_BEAT_BYTES);
    switch (off) {
    case RTLNET_REG_ID:                      return RTLNET_S2MM_ID_VALUE;
    case RTLNET_REG_VERSION:                 return HOST_VID_VERSION;
    case RTLNET_REG_CAPS:                    return RTLNET_S2MM_MAX_BURST_BEATS | (RTLNET_S2MM_BEAT_BYTES << RTLNET_S2MM_CAPS_BYTES_SHIFT) |
                                                    (29u << RTLNET_S2MM_CAPS_ADDR_SHIFT);
    case RTLNET_S2MM_REG_CTRL:               return g_dma_ctrl & RTLNET_S2MM_CTRL_ENABLE;
    case RTLNET_S2MM_REG_STATUS:             return 0u;
    case RTLNET_S2MM_REG_STRIDE:             return g_dma_stride;
    case RTLNET_S2MM_REG_FRAMES_OK:          return ok;
    case RTLNET_S2MM_REG_BURSTS:             return ok * (beats / RTLNET_S2MM_MAX_BURST_BEATS);
    case RTLNET_S2MM_REG_BEATS:              return ok * beats;
    case RTLNET_S2MM_REG_LAST_BASE:          return HOST_VID_FB_OFFSET + (host_vid_slot(g_vid_frames) * HOST_VID_SLOT_BYTES);
    default:                                 return 0u;
    }
}

/**
 * @brief Model of the rtlnet_vdma_s2mm register writes.
 * @param off   Register offset.
 * @param value Value.
 * @return None.
 */
static void host_s2mm_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_S2MM_REG_CTRL) {
        g_dma_ctrl = value & RTLNET_S2MM_CTRL_ENABLE;
        if ((value & RTLNET_S2MM_CTRL_CNT_CLEAR) != 0u) {
            g_vid_base = g_vid_frames;
        }
    } else if (off == RTLNET_S2MM_REG_STRIDE) {
        g_dma_stride = value;
    }
}

/**
 * @brief Model of the rtlnet_framebuf register read mux.
 * @param off Register offset.
 * @return Register value.
 */
static uint32_t host_fb_read(uint32_t off)
{
    uint32_t latest = host_vid_slot(g_vid_frames);
    uint32_t lmode = g_csi_mode;
    switch (off) {
    case RTLNET_REG_ID:                  return RTLNET_FB_ID_VALUE;
    case RTLNET_REG_VERSION:             return HOST_VID_VERSION;
    case RTLNET_REG_CAPS:                return HOST_VID_SLOTS | (1u << RTLNET_FB_CAPS_READERS_SHIFT) |
                                                (HOST_VID_SLOT_LOG2 << RTLNET_FB_CAPS_SLOTLOG2_SHIFT) | (29u << RTLNET_FB_CAPS_ADDR_SHIFT);
    case RTLNET_FB_REG_STATUS:           return ((g_vid_frames != 0u) ? RTLNET_FB_STATUS_LATEST_VALID : 0u) |
                                                (g_fb_holds ? RTLNET_FB_STATUS_FW_HOLDS : 0u) | g_fb_err |
                                                (latest << RTLNET_FB_STATUS_LATEST_SHIFT) | (g_fb_fw_slot << RTLNET_FB_STATUS_FWSLOT_SHIFT);
    case RTLNET_FB_REG_FB_BASE:          return HOST_VID_FB_OFFSET;
    case RTLNET_FB_REG_SLOT_BYTES:       return HOST_VID_SLOT_BYTES;
    case RTLNET_FB_REG_LATEST_BASE:      return HOST_VID_FB_OFFSET + (latest * HOST_VID_SLOT_BYTES);
    case RTLNET_FB_REG_LATEST_FRAME:     return g_vid_frames;
    case RTLNET_FB_REG_LATEST_TS:        return g_vid_frames * g_csi_period;
    case RTLNET_FB_REG_LATEST_WH:        return (rtlnet_csi2_rx_mode_height(lmode) << 16) | rtlnet_csi2_rx_mode_width(lmode);
    case RTLNET_FB_REG_LATEST_SRC:       return 1u;
    case RTLNET_FB_REG_FW_BASE:          return HOST_VID_FB_OFFSET + (g_fb_fw_slot * HOST_VID_SLOT_BYTES);
    case RTLNET_FB_REG_FW_FRAME:         return g_fb_fw_frame;
    case RTLNET_FB_REG_FW_TS:            return g_fb_fw_frame * g_csi_period;
    case RTLNET_FB_REG_FW_WH:            return (rtlnet_csi2_rx_mode_height(g_fb_fw_mode) << 16) | rtlnet_csi2_rx_mode_width(g_fb_fw_mode);
    case RTLNET_FB_REG_FW_SRC:           return 1u;
    case RTLNET_FB_REG_PUBLISHED:        return g_vid_frames - g_vid_base;
    case RTLNET_FB_REG_FW_TAKES:         return g_fb_takes;
    case RTLNET_FB_REG_REFCNT + 0u:      return (g_fb_holds && g_fb_fw_slot == 0u) ? 1u : 0u;
    case RTLNET_FB_REG_REFCNT + 4u:      return (g_fb_holds && g_fb_fw_slot == 1u) ? 1u : 0u;
    case RTLNET_FB_REG_REFCNT + 8u:      return (g_fb_holds && g_fb_fw_slot == 2u) ? 1u : 0u;
    default:                             return 0u;
    }
}

/**
 * @brief Model of the rtlnet_framebuf register writes: FW_TAKE and FW_RELEASE with the sticky FW_ERR, CNT_CLEAR.
 * @param off   Register offset.
 * @param value Value.
 * @return None.
 */
static void host_fb_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_FB_REG_STATUS) {
        g_fb_err &= ~(value & HOST_VID_ERR_FB);
    } else if (off == RTLNET_FB_REG_CTRL) {
        if ((value & RTLNET_FB_CTRL_FW_TAKE) != 0u) {
            if (g_vid_frames == 0u || g_fb_holds) {
                g_fb_err |= HOST_VID_ERR_FB;
            } else {
                g_fb_holds    = 1;
                g_fb_fw_slot  = host_vid_slot(g_vid_frames);
                g_fb_fw_frame = g_vid_frames;
                g_fb_fw_mode  = g_csi_mode;
                g_fb_takes++;
                host_vid_fill(g_fb_fw_slot, g_fb_fw_mode);
            }
        }
        if ((value & RTLNET_FB_CTRL_FW_RELEASE) != 0u) {
            if (!g_fb_holds) {
                g_fb_err |= HOST_VID_ERR_FB;
            } else {
                g_fb_holds = 0;
            }
        }
        if ((value & RTLNET_FB_CTRL_CNT_CLEAR) != 0u) {
            g_vid_base = g_vid_frames;
            g_fb_takes = 0u;
        }
    }
}

/**
 * @brief Held-slot state of the framebuf model, for the harness checks.
 * @return 1 while the firmware holds a slot.
 */
int host_model_video_fw_holds(void)
{
    return g_fb_holds;
}

/**
 * @brief Model of the board system-register read mux.
 * @param off Register offset.
 * @return Register value (fixed values, a running uptime, the RW registers).
 */
static uint32_t host_sysreg_read(uint32_t off)
{
    switch (off) {
    case NXV_SYS_ID:          return NXV_SYS_ID_VALUE;
    case NXV_SYS_VERSION:     return NXV_SYS_VERSION_VALUE;
    case NXV_SYS_CAPS:        return (5u << NXV_CAPS_NUM_BTN_SHIFT) | (8u << NXV_CAPS_NUM_SW_SHIFT) |
                                     (8u << NXV_CAPS_NUM_LEDS_SHIFT);
    case NXV_SYS_BUILD_ID:    return 0x1234ABCDu;
    case NXV_SYS_BUILD_DIRTY: return 0u;
    case NXV_SYS_LEDS:        return g_leds & NXV_LED_WRITABLE_MASK;
    case NXV_SYS_SWITCHES:    return 0xA5u;
    case NXV_SYS_BUTTONS:     return NXV_BTN_C;
    case NXV_SYS_CLK_STATUS:  return NXV_CLK_MMCM_LOCKED | (g_ddr_cal ? NXV_CLK_DDR_CALIB : 0u) |
                                     (0x1Fu << NXV_CLK_ALIVE_SHIFT);
    case NXV_SYS_SCRATCH:     return g_scratch;
    case NXV_SYS_UPTIME_MS:   return plat_uptime_ms();
    case NXV_SYS_CPU_CLK_HZ:  return RTLNET_PLAT_CPU_CLK_HZ;
    case NXV_SYS_PHY_STATUS:  return NXV_PHY_INT_N | NXV_PHY_PME_N | NXV_PHY_RST_N | NXV_PHY_MDIO_IN;
    case NXV_SYS_NET_STATUS:  return 0u;
    case NXV_SYS_CLK_MEAS0 + 0u:  return 7812u;    /* 124.992 MHz */
    case NXV_SYS_CLK_MEAS0 + 4u:  return 7812u;
    case NXV_SYS_CLK_MEAS0 + 8u:  return 12500u;   /* 200.000 MHz */
    case NXV_SYS_CLK_MEAS0 + 12u: return 3906u;    /* 62.496 MHz */
    case NXV_SYS_CLK_MEAS0 + 16u: return 3125u;    /* 50.000 MHz */
    default:                  return 0u;
    }
}

/**
 * @brief rtlnet_mmio.h host hook: 32-bit read.
 * @param addr Byte address.
 * @return Model value: system registers, present-core headers, stored words,
 *         else 0 (an absent core's window).
 */
uint32_t rtlnet_host_reg_read32(uintptr_t addr)
{
    g_reg_acc++;
    host_h264_on_access();   /* the encoder model runs while the firmware works (host_model_h264_timing) */
    if (g_cls_on && addr >= RTLNET_PLAT_CLS_BASE && addr < RTLNET_PLAT_CLS_BASE + RTLNET_CLS_WINDOW_BYTES) {
        return host_cls_read((uint32_t)(addr - RTLNET_PLAT_CLS_BASE));
    }
    if (g_txo_on && addr >= RTLNET_PLAT_TXO_BASE && addr < RTLNET_PLAT_TXO_BASE + RTLNET_TXO_WINDOW_BYTES) {
        return host_txo_read((uint32_t)(addr - RTLNET_PLAT_TXO_BASE));
    }
    if (g_vid_on && addr >= RTLNET_PLAT_CSI2_BASE && addr < RTLNET_PLAT_CSI2_BASE + 0x1000u) {
        return host_csi2_read((uint32_t)(addr - RTLNET_PLAT_CSI2_BASE));
    }
    if (g_vid_on && addr >= RTLNET_PLAT_S2MM_BASE && addr < RTLNET_PLAT_S2MM_BASE + 0x1000u) {
        return host_s2mm_read((uint32_t)(addr - RTLNET_PLAT_S2MM_BASE));
    }
    if (g_vid_on && addr >= RTLNET_PLAT_FB_BASE && addr < RTLNET_PLAT_FB_BASE + 0x1000u) {
        return host_fb_read((uint32_t)(addr - RTLNET_PLAT_FB_BASE));
    }
    if (g_ddr_arb_on && addr >= RTLNET_PLAT_ARB_BASE && addr < RTLNET_PLAT_ARB_BASE + 0x1000u) {
        return host_arb_read((uint32_t)(addr - RTLNET_PLAT_ARB_BASE));
    }
    if (host_h264_active() && addr >= RTLNET_PLAT_H264_BASE && addr < RTLNET_PLAT_H264_BASE + 0x1000u) {
        return host_h264_read((uint32_t)(addr - RTLNET_PLAT_H264_BASE));
    }
    if (g_wrap_on == 1 && addr == RTLNET_PLAT_PROT_BASE + 0x008u) {
        return 0x00000020u;                    /* CAPS: CPU_PATH_PRESENT */
    }
    if (g_wrap_on == 1 && addr == RTLNET_PLAT_PROT_BASE + 0x034u) {
        return g_wrap_cpu_caps;
    }
    if (addr >= RTLNET_PLAT_SYS_BASE && addr < RTLNET_PLAT_SYS_BASE + 0x1000u) {
        return host_sysreg_read((uint32_t)(addr - RTLNET_PLAT_SYS_BASE));
    }
    for (unsigned i = 0; i < HOST_MAX_CORES; i++) {
        if (g_core_id[i] != 0u && addr >= g_core_base[i] && addr < g_core_base[i] + 0x10u) {
            switch ((uint32_t)(addr - g_core_base[i])) {
            case RTLNET_REG_ID:      return g_core_id[i];
            case RTLNET_REG_VERSION: return HOST_CORE_VERSION;
            default:                 return 0u;
            }
        }
    }
    for (unsigned i = 0; i < HOST_MAX_WORDS; i++) {
        if (g_word_addr[i] == addr && addr != 0u) {
            return g_word_val[i];
        }
    }
    return 0u;
}

/**
 * @brief rtlnet_mmio.h host hook: 32-bit write.
 * @param addr  Byte address.
 * @param value Value.
 * @return None. LEDS and SCRATCH are modelled; other system offsets ignore
 *         writes; core windows ignore writes; any other address is stored.
 */
void rtlnet_host_reg_write32(uintptr_t addr, uint32_t value)
{
    g_reg_acc++;
    host_h264_on_access();
    if (g_cls_on && addr >= RTLNET_PLAT_CLS_BASE && addr < RTLNET_PLAT_CLS_BASE + RTLNET_CLS_WINDOW_BYTES) {
        host_cls_write((uint32_t)(addr - RTLNET_PLAT_CLS_BASE), value);
        return;
    }
    if (g_txo_on && addr >= RTLNET_PLAT_TXO_BASE && addr < RTLNET_PLAT_TXO_BASE + RTLNET_TXO_WINDOW_BYTES) {
        host_txo_write((uint32_t)(addr - RTLNET_PLAT_TXO_BASE), value);
        return;
    }
    if (g_vid_on && addr >= RTLNET_PLAT_CSI2_BASE && addr < RTLNET_PLAT_CSI2_BASE + 0x1000u) {
        host_csi2_write((uint32_t)(addr - RTLNET_PLAT_CSI2_BASE), value);
        return;
    }
    if (g_vid_on && addr >= RTLNET_PLAT_S2MM_BASE && addr < RTLNET_PLAT_S2MM_BASE + 0x1000u) {
        host_s2mm_write((uint32_t)(addr - RTLNET_PLAT_S2MM_BASE), value);
        return;
    }
    if (g_vid_on && addr >= RTLNET_PLAT_FB_BASE && addr < RTLNET_PLAT_FB_BASE + 0x1000u) {
        host_fb_write((uint32_t)(addr - RTLNET_PLAT_FB_BASE), value);
        return;
    }
    if (g_ddr_arb_on && addr >= RTLNET_PLAT_ARB_BASE && addr < RTLNET_PLAT_ARB_BASE + 0x1000u) {
        host_arb_write((uint32_t)(addr - RTLNET_PLAT_ARB_BASE), value);
        return;
    }
    if (host_h264_active() && addr >= RTLNET_PLAT_H264_BASE && addr < RTLNET_PLAT_H264_BASE + 0x1000u) {
        host_h264_write((uint32_t)(addr - RTLNET_PLAT_H264_BASE), value);
        return;
    }
    if (addr >= RTLNET_PLAT_SYS_BASE && addr < RTLNET_PLAT_SYS_BASE + 0x1000u) {
        uint32_t off = (uint32_t)(addr - RTLNET_PLAT_SYS_BASE);
        if (off == NXV_SYS_LEDS) {
            g_leds = value & NXV_LED_WRITABLE_MASK;
        } else if (off == NXV_SYS_SCRATCH) {
            g_scratch = value;
        }
        return;
    }
    if (addr >= RTLNET_PLAT_WINDOW_BASE && addr < RTLNET_PLAT_WINDOW_BASE + RTLNET_CPU_RTLNET_SIZE) {
        return;
    }
    for (unsigned i = 0; i < HOST_MAX_WORDS; i++) {
        if (g_word_addr[i] == addr || g_word_addr[i] == 0u) {
            g_word_addr[i] = addr;
            g_word_val[i]  = value;
            return;
        }
    }
}

/**
 * @brief MDIO driver host hook (rtlnet_mdio.c under RTLNET_HOST_TEST): the
 *        MDC half-period spin takes no time in the model.
 * @param loops Spin count requested by the driver.
 * @return None.
 */
void rtlnet_host_spin(uint32_t loops);
void rtlnet_host_spin(uint32_t loops)
{
    (void)loops;
}

/* Interrupt controller model: handlers per INTC input, the enable mask, the input lines the models drive, and the CPU interrupt mask (a critical
 * section, or a handler running). A handler is called when its input is enabled, its line is high and the CPU interrupts are not masked: from
 * host_irq_deliver (called when a model changes a line, and when plat_irq_restore unmasks), so the code under test sees the interrupt between
 * any two register accesses, never inside a critical section. */
static void   (*g_irq_handler[RTLNET_CPU_IRQ_COUNT])(void *);
static void    *g_irq_ref[RTLNET_CPU_IRQ_COUNT];
static uint32_t g_irq_enabled;
static uint32_t g_irq_lines;
static int      g_irq_masked;
static int      g_irq_in_deliver;
static uint32_t g_irq_delivered;
static uint32_t g_irq_acc_total;      /* register accesses made inside handler calls */
static uint32_t g_irq_acc_max;        /* the most in one handler call */

/**
 * @brief Mask the CPU interrupts (nesting safe).
 * @return 8 when they were unmasked (the RISC-V mstatus.MIE bit), 0 when already masked; for plat_irq_restore.
 */
uint32_t plat_irq_save(void)
{
    uint32_t prev = g_irq_masked ? 0u : 8u;
    g_irq_masked = 1;
    return prev;
}

/**
 * @brief Return to the state plat_irq_save found; unmasking delivers a pending interrupt.
 * @param state Value from plat_irq_save.
 * @return None.
 */
void plat_irq_restore(uint32_t state)
{
    if ((state & 8u) != 0u) {
        g_irq_masked = 0;
        host_irq_deliver();
    }
}

/**
 * @brief Connect a handler on an INTC input; the input stays masked.
 * @param input   INTC input.
 * @param handler Handler.
 * @param ref     Argument of the handler.
 * @return 0, or -1 for an input out of range.
 */
int plat_irq_attach(unsigned input, void (*handler)(void *), void *ref)
{
    if (input >= RTLNET_CPU_IRQ_COUNT || handler == NULL) {
        return -1;
    }
    g_irq_handler[input] = handler;
    g_irq_ref[input] = ref;
    return 0;
}

/**
 * @brief Unmask or mask an INTC input.
 * @param input INTC input.
 * @param on    1 unmask, 0 mask.
 * @return None.
 */
void plat_irq_enable(unsigned input, int on)
{
    if (input >= RTLNET_CPU_IRQ_COUNT) {
        return;
    }
    if (on != 0) {
        g_irq_enabled |= 1u << input;
        host_irq_deliver();
    } else {
        g_irq_enabled &= ~(1u << input);
    }
}

/**
 * @brief A model drives an input line.
 * @param input INTC input.
 * @param level 1 high, 0 low.
 * @return None.
 */
void host_irq_set_line(unsigned input, uint32_t level)
{
    if (input >= RTLNET_CPU_IRQ_COUNT) {
        return;
    }
    if (level != 0u) {
        g_irq_lines |= 1u << input;
    } else {
        g_irq_lines &= ~(1u << input);
    }
}

/**
 * @brief Call the handlers of the inputs that are high and enabled while the CPU interrupts are unmasked (level sensitive: a handler that leaves
 *        the line high is called again, at most 8 times per call).
 * @return None.
 */
void host_irq_deliver(void)
{
    if (g_irq_in_deliver) {
        return;
    }
    g_irq_in_deliver = 1;
    for (int n = 0; n < 8 && !g_irq_masked; n++) {
        unsigned in = RTLNET_CPU_IRQ_COUNT;
        for (unsigned i = 0; i < RTLNET_CPU_IRQ_COUNT; i++) {
            if (((g_irq_lines & g_irq_enabled) & (1u << i)) != 0u && g_irq_handler[i] != NULL) {
                in = i;
                break;
            }
        }
        if (in == RTLNET_CPU_IRQ_COUNT) {
            break;
        }
        g_irq_masked = 1;      /* the trap masks the CPU interrupts while the handler runs */
        g_irq_delivered++;
        {
            uint32_t a0 = g_reg_acc;
            g_irq_handler[in](g_irq_ref[in]);
            a0 = g_reg_acc - a0;
            g_irq_acc_total += a0;
            if (a0 > g_irq_acc_max) {
                g_irq_acc_max = a0;
            }
        }
        g_irq_masked = 0;
    }
    g_irq_in_deliver = 0;
}

/**
 * @brief Handler calls made so far.
 * @return Count.
 */
uint32_t host_irq_delivered(void)
{
    return g_irq_delivered;
}

/**
 * @brief Register accesses made inside interrupt handler calls.
 * @param calls Receives the handler calls.
 * @param total Receives the accesses summed over the calls.
 * @param max   Receives the most accesses in one call.
 * @return None.
 */
void host_irq_access_stats(uint32_t *calls, uint32_t *total, uint32_t *max)
{
    *calls = g_irq_delivered;
    *total = g_irq_acc_total;
    *max = g_irq_acc_max;
}

/**
 * @brief Write bytes into the DDR3 model without counting an arbiter access (the encoder model's DMA writes).
 * @param ddr_off Byte offset in the DDR3 window.
 * @param data    Bytes.
 * @param n       Count.
 * @return None.
 */
void host_ddr_poke(uint32_t ddr_off, const uint8_t *data, uint32_t n)
{
    for (uint32_t i = 0u; i < n; i++) {
        uintptr_t a = (uintptr_t)(RTLNET_PLAT_DDR_BASE + ((ddr_off + i) & ~3u));
        uint32_t *pg = host_ddr_page(a, 1);
        if (pg != NULL) {
            uint32_t sh = 8u * ((ddr_off + i) & 3u);
            uint32_t *w = &pg[host_ddr_word(a)];
            *w = (*w & ~(0xFFu << sh)) | ((uint32_t)data[i] << sh);
        }
    }
}

/**
 * @brief Platform start: time origin, LEDs cleared.
 * @return None.
 */
void plat_init(void)
{
    g_t0 = clock();
    g_leds = 0u;
    memset(g_irq_handler, 0, sizeof(g_irq_handler));
    memset(g_irq_ref, 0, sizeof(g_irq_ref));
    g_irq_enabled = 0u;
    g_irq_masked = 0;
}

/**
 * @brief Console output: capture (for the demo checks) and optionally stdout.
 * @param s Text.
 * @param n Characters.
 * @return None.
 */
void plat_console_write(const char *s, size_t n)
{
    size_t room = HOST_CAPTURE_MAX - 1u - g_capture_len;
    size_t k = (n < room) ? n : room;
    memcpy(&g_capture[g_capture_len], s, k);
    g_capture_len += k;
    g_capture[g_capture_len] = '\0';
    if (g_echo) {
        (void)fwrite(s, 1u, n, stdout);
        (void)fflush(stdout);
    }
}

/**
 * @brief Console input is fed by host/main.c directly; never ready here.
 * @return -1.
 */
int plat_console_getc(void)
{
    return -1;
}

/**
 * @brief Console transmit counters: the harness writes straight to stdout, so all are zero.
 * @param out Receives the counters.
 */
void plat_console_tx_stats(plat_console_tx_t *out)
{
    out->ring_bytes = 0u;
    out->high_water = 0u;
    out->irqs = 0u;
    out->refills = 0u;
    out->drops = 0u;
    out->irq_mode = 0u;
}

/**
 * @brief Milliseconds since plat_init (processor time of the harness).
 * @return Elapsed milliseconds.
 */
uint32_t plat_uptime_ms(void)
{
    return (uint32_t)(((uint64_t)(clock() - g_t0) * 1000u) / (uint64_t)CLOCKS_PER_SEC);
}

/**
 * @brief Free-running tick of the host model (microseconds of processor time
 *        times RTLNET_PLAT_TICKS_PER_US).
 * @return Tick count.
 */
uint32_t plat_ticks(void)
{
    return (uint32_t)(((uint64_t)(clock() - g_t0) * 1000000u / (uint64_t)CLOCKS_PER_SEC) * RTLNET_PLAT_TICKS_PER_US);
}

/**
 * @brief Delay (no-op on the host: nothing waits on hardware).
 * @param us Microseconds.
 * @return None.
 */
void plat_delay_us(uint32_t us)
{
    (void)us;
}

/**
 * @brief Delay (no-op on the host).
 * @param ms Milliseconds.
 * @return None.
 */
void plat_delay_ms(uint32_t ms)
{
    (void)ms;
}

/**
 * @brief Periodic work (none on the host).
 * @return None.
 */
void plat_poll(void)
{
}

/**
 * @brief LED control into the model's LEDS register (index 1..7).
 * @param index LED number.
 * @param on    1 on, 0 off.
 * @return None.
 */
void plat_led_set(unsigned index, int on)
{
    if (index >= 1u && index <= 7u) {
        uint32_t mask = 1u << index;
        g_leds = on ? (g_leds | mask) : (g_leds & ~mask);
    }
}

/**
 * @brief LED shadow.
 * @return Bits [7:1].
 */
uint32_t plat_led_state(void)
{
    return g_leds;
}

